"""FastAPI Router for browser extension telemetry ingestion."""

from __future__ import annotations

from datetime import datetime
from typing import Any, Literal

from fastapi import APIRouter
from pydantic import BaseModel, Field

from src.backend.logging import get_logger

router = APIRouter(prefix="/telemetry", tags=["Telemetry"])
logger = get_logger("api.telemetry")


class TelemetryLogEntry(BaseModel):
    """A single structured log event generated by the browser extension."""

    timestamp_ms: float = Field(
        ...,
        description="Epoch timestamp in milliseconds recorded at event occurrence.",
    )
    level: Literal["DEBUG", "INFO", "WARNING", "ERROR"] = Field(
        default="INFO",
        description="Logging severity level.",
    )
    module: str = Field(
        ...,
        description="Extension module identifier (e.g. 'CS', 'SW', 'Prefetch', 'Popup').",
    )
    message: str = Field(
        ...,
        description="Human-readable informational or error message.",
    )
    trace_id: str | None = Field(
        default=None,
        description="Correlation trace ID matching translation pipeline context.",
    )
    extra: dict[str, Any] | None = Field(
        default=None,
        description="Optional structured metadata attributes.",
    )


class TelemetryBatchRequest(BaseModel):
    """Payload envelope containing batched extension telemetry logs."""

    logs: list[TelemetryLogEntry] = Field(
        default_factory=list,
        description="Ordered sequence of buffered telemetry events.",
    )


class TelemetryBatchResponse(BaseModel):
    """Response returned upon successful telemetry batch ingestion."""

    success: bool = True
    count: int = 0


@router.post("/logs", response_model=TelemetryBatchResponse)
async def ingest_telemetry_batch(
    payload: TelemetryBatchRequest,
) -> TelemetryBatchResponse:
    """Ingest a batch of extension log events and format them to extension.log."""
    for entry in payload.logs:
        sub_namespace = f"extension.{entry.module.lower()}"
        ext_logger = get_logger(sub_namespace)

        dt = datetime.fromtimestamp(entry.timestamp_ms / 1000.0)
        formatted_time = dt.strftime("%Y-%m-%d %H:%M:%S") + f".{int(entry.timestamp_ms % 1000):03d}"

        trace_part = f"[{entry.trace_id}] " if entry.trace_id else ""
        extra_part = f" (extra: {entry.extra})" if entry.extra else ""
        log_line = f"{formatted_time} [{entry.level:<7}] [inkshift.{sub_namespace}] {trace_part}{entry.message}{extra_part}"

        log_fn = getattr(ext_logger, entry.level.lower(), ext_logger.info)
        log_fn(log_line)

    return TelemetryBatchResponse(success=True, count=len(payload.logs))
